package vn.covie.cart.persistence; import java.util.*; import jakarta.persistence.LockModeType; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import vn.covie.cart.model.*;
public interface CartRepository extends JpaRepository<CartEntity,UUID>{Optional<CartEntity> findByUserIdAndMerchantLocationIdAndCartTypeAndCartStatus(UUID user,UUID location,CartType type,CartStatus status);List<CartEntity> findByUserIdAndCartStatusOrderByUpdatedAtDesc(UUID user,CartStatus status);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select c from CartEntity c where c.id=:cartId and c.userId=:userId and c.cartStatus='ACTIVE'")Optional<CartEntity> findActiveByIdAndUserIdForUpdate(@Param("cartId")UUID cartId,@Param("userId")UUID userId);}
